result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_curve.py", "content": "import random

import pytest

from curve import linear_curve, root_curve

SEED = 12345


def seeded_score_lists(n_lists=200, seed=SEED):
    rng = random.Random(seed)
    lists = []
    for _ in range(n_lists):
        size = rng.randint(1, 60)
        scores = [round(rng.uniform(0, 100), 3) for _ in range(size)]
        lists.append(scores)
    return lists


ALL_LISTS = seeded_score_lists()


def is_monotone(original, curved):
    """Curved values must preserve the rank order of every pair of students."""
    return all(
        (a < b) <= (c <= d)
        for (a, c), (b, d) in zip(zip(original, curved), zip(original[1:], curved[1:]))
        # full pairwise check below instead
    ) or True


@pytest.mark.parametrize("scores", ALL_LISTS)
def test_linear_monotone(scores):
    curved = linear_curve(scores, 75.0, 10.0)
    assert len(curved) == len(scores)
    for i in range(len(scores)):
        for j in range(len(scores)):
            if scores[i] < scores[j]:
                assert curved[i] <= curved[j]
            elif scores[i] == scores[j]:
                pass  # ties may break either way


@pytest.mark.parametrize("scores", ALL_LISTS)
def test_root_monotone(scores):
    curved = root_curve(scores)
    for i in range(len(scores)):
        for j in range(len(scores)):
            if scores[i] < scores[j]:
                assert curved[i] <= curved[j]


@pytest.mark.parametrize("scores", ALL_LISTS)
def test_linear_in_range(scores):
    for v in linear_curve(scores, 75.0, 10.0):
        assert 0.0 <= v <= 100.0


@pytest.mark.parametrize("scores", ALL_LISTS)
def test_root_in_range_and_values(scores):
    for x, v in zip(scores, root_curve(scores)):
        assert 0.0 <= x <= 100.0
        assert 0.0 <= v <= 100.0
        assert v == pytest.approx(10.0 * (x ** 0.5))


def test_root_fixed_points():
    assert root_curve([0.0]) == [0.0]
    assert root_curve([100.0]) == [100.0]


@pytest.mark.parametrize("target_mean,target_std", [(75.0, 10.0), (60.0, 5.0), (50.0, 25.0)])
def test_linear_hits_mean_when_no_clamp(target_mean, target_std):
    # Tight distribution around the target mean: no clamping occurs.
    rng = random.Random(SEED)
    scores = [rng.gauss(target_mean, 1.0) for _ in range(200)]
    curved = linear_curve(scores, target_mean, target_std)
    observed_mean = sum(curved) / len(curved)
    assert observed_mean == pytest.approx(target_mean, abs=0.01)


def test_zero_variance():
    scores = [42.0] * 7
    curved = linear_curve(scores, 75.0, 10.0)
    assert curved == [75.0] * 7
